const path = require("path");
const { Resvg } = require("@resvg/resvg-js");

const FONT_DIR = path.join(__dirname, "..", "fonts");

// Strip anything that could execute or reach out to the network. Designs are
// generated by an LLM from user input, so treat the markup as untrusted.
function sanitizeSvg(svg) {
  return svg
    .replace(/<script[\s\S]*?<\/script\s*>/gi, "")
    .replace(/<script[^>]*\/>/gi, "")
    .replace(/<foreignObject[\s\S]*?<\/foreignObject\s*>/gi, "")
    .replace(/<(iframe|object|embed|audio|video)[\s\S]*?(<\/\1\s*>|\/>)/gi, "")
    .replace(/\son[a-z]+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi, "")
    .replace(/(href|xlink:href)\s*=\s*("|')\s*(?!#|data:image\/)[^"']*\2/gi, "")
    .replace(/@import[^;]*;/gi, "")
    .replace(/url\(\s*(['"]?)(?!#)[^)]*\)/gi, "none");
}

// Pull the first complete <svg>...</svg> element out of a model response.
function extractSvg(text) {
  const match = text.match(/<svg[\s\S]*<\/svg>/i);
  return match ? match[0] : null;
}

// Force the root element to the exact canvas so rasterizing is predictable.
function normalizeRoot(svg, width, height) {
  return svg.replace(/<svg\b[^>]*>/i, (tag) => {
    let out = tag
      .replace(/\swidth\s*=\s*("[^"]*"|'[^']*')/i, "")
      .replace(/\sheight\s*=\s*("[^"]*"|'[^']*')/i, "");
    if (!/viewBox\s*=/i.test(out)) {
      out = out.replace(/<svg/i, `<svg viewBox="0 0 ${width} ${height}"`);
    }
    if (!/xmlns\s*=/i.test(out)) {
      out = out.replace(/<svg/i, '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    return out.replace(/<svg/i, `<svg width="${width}" height="${height}"`);
  });
}

function prepareSvg(rawSvg, width, height) {
  return normalizeRoot(sanitizeSvg(rawSvg), width, height);
}

function addWatermark(svg, width, height) {
  const size = Math.round(Math.max(width, height) * 0.018);
  const pad = Math.round(size * 0.9);
  const mark =
    `<g opacity="0.55" font-family="Inter" font-weight="700" font-size="${size}">` +
    `<rect x="${width - size * 11.2 - pad}" y="${height - size * 1.9 - pad}" width="${size * 11.2}" height="${size * 1.9}" rx="${size * 0.4}" fill="#000"/>` +
    `<text x="${width - size * 5.6 - pad}" y="${height - pad - size * 0.6}" fill="#fff" text-anchor="middle">DesignForge AI · free</text>` +
    `</g>`;
  return svg.replace(/<\/svg>\s*$/i, `${mark}</svg>`);
}

function renderPng(svg, targetLongestSide, width, height) {
  const fitTo =
    width >= height
      ? { mode: "width", value: targetLongestSide }
      : { mode: "height", value: targetLongestSide };
  const resvg = new Resvg(svg, {
    fitTo,
    background: "#ffffff",
    font: {
      fontDirs: [FONT_DIR],
      loadSystemFonts: true,
      defaultFontFamily: "Inter",
      sansSerifFamily: "Inter",
      serifFamily: "DejaVu Serif",
    },
  });
  return resvg.render().asPng();
}

module.exports = { prepareSvg, extractSvg, addWatermark, renderPng };
